// Brand these three so they stop being interchangeable numbers.
type OrderId = number;
type CustomerId = number;
type Cents = number;

function toOrderId(n: number): OrderId {
  if (!Number.isInteger(n) || n < 1000) throw new Error(`Invalid order id: ${n}`);
  return n;
}

function toCustomerId(n: number): CustomerId {
  if (!Number.isInteger(n) || n < 1) throw new Error(`Invalid customer id: ${n}`);
  return n;
}

function toCents(n: number): Cents {
  if (!Number.isSafeInteger(n)) throw new Error(`Cents must be a whole number, got ${n}`);
  return n;
}

type Currency = 'USD' | 'EUR' | 'EGP';
type Money<C extends Currency = Currency> = { cents: Cents; currency: C };

function money<C extends Currency>(cents: number, currency: C): Money<C> {
  return { cents: toCents(cents), currency };
}

function add<C extends Currency>(a: Money<C>, b: Money<C>): Money<C> {
  return { cents: toCents(a.cents + b.cents), currency: a.currency };
}

type PaymentMethod =
  | { kind: 'card'; last4: string }
  | { kind: 'wallet'; provider: 'apple' | 'google' }
  | { kind: 'cash-on-delivery' };

function describePayment(p: PaymentMethod): string {
  switch (p.kind) {
    case 'card': return `Card ending ${p.last4}`;
    case 'wallet': return `${p.provider === 'apple' ? 'Apple' : 'Google'} wallet`;
  }
}

