declare const brand: unique symbol;
type Brand<T, B extends string> = T & { readonly [brand]: B };

type OrderId = Brand<number, 'OrderId'>;
type CustomerId = Brand<number, 'CustomerId'>;
type Cents = Brand<number, 'Cents'>;

function toOrderId(n: number): OrderId {
  if (!Number.isInteger(n) || n < 1000) throw new Error(`Invalid order id: ${n}`);
  return n as OrderId;
}

function toCustomerId(n: number): CustomerId {
  if (!Number.isInteger(n) || n < 1) throw new Error(`Invalid customer id: ${n}`);
  return n as CustomerId;
}

function toCents(n: number): Cents {
  if (!Number.isSafeInteger(n)) throw new Error(`Cents must be a whole number, got ${n}`);
  return n as Cents;
}

type Currency = 'USD' | 'EUR' | 'EGP';
type Money<C extends Currency = Currency> = { cents: Cents; currency: C };

function money<C extends Currency>(cents: number, currency: C): Money<C> {
  return { cents: toCents(cents), currency };
}

function add<C extends Currency>(a: Money<C>, b: Money<NoInfer<C>>): Money<C> {
  return { cents: toCents(a.cents + b.cents), currency: a.currency };
}

type PaymentMethod =
  | { kind: 'card'; last4: string }
  | { kind: 'wallet'; provider: 'apple' | 'google' }
  | { kind: 'cash-on-delivery' };

function assertNever(value: never): never {
  throw new Error(`Unhandled value: ${JSON.stringify(value)}`);
}

function describePayment(p: PaymentMethod): string {
  switch (p.kind) {
    case 'card': return `Card ending ${p.last4}`;
    case 'wallet': return `${p.provider === 'apple' ? 'Apple' : 'Google'} wallet`;
    case 'cash-on-delivery': return 'Cash on delivery';
    default: return assertNever(p);
  }
}

// ---- Type tests (do not edit) ----
type T1 = Expect<NotEqual<OrderId, number>>;
type T2 = Expect<NotEqual<OrderId, CustomerId>>;
type T3 = Expect<Equal<OrderId extends number ? true : false, true>>;

function typeTests(customer: CustomerId, usd: Money<'USD'>, eur: Money<'EUR'>) {
  // @ts-expect-error: a customer id is not an order id
  const fromCustomer: OrderId = customer;
  // @ts-expect-error: plain numbers must go through toOrderId
  const fromNumber: OrderId = 1042;
  // @ts-expect-error: dollars and euros cannot be added
  add(usd, eur);
  const total = add(usd, usd);
  type T4 = Expect<Equal<typeof total, Money<'USD'>>>;
}

console.log(add(money(18900, 'USD'), money(499, 'USD')), describePayment({ kind: 'cash-on-delivery' }));
